arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_43f009714f33476f92529dfb719c68a2.Models
@using sv_43f009714f33476f92529dfb719c68a2.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @* ───── Step Indicator Bar ───── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        <div class="position-absolute" style="top: 20px; left: 10%; right: 10%; height: 2px; background: #dee2e6; z-index: 0;"></div>
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <div class="text-center position-relative" style="z-index: 1; flex: 1;">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center border-0 @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary opacity-50")"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture || _submitted)"
                        @onclick="() => GoToStep(step)">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                    @StepLabels[i]
                </div>
            </div>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger alert-dismissible fade show" role="alert">
            @_errorMessage
            <button type="button" class="btn-close" @onclick='() => _errorMessage = ""'></button>
        </div>
    }

    @if (_submitted)
    {
        @* ───── Confirmation ───── *@
        <div class="text-center py-5">
            <div class="display-1 text-success mb-3">✓</div>
            <h2>Application Submitted!</h2>
