@page "/apply"
@rendermode InteractiveServer
@using sv_43f009714f33476f92529dfb719c68a2.Models
@using sv_43f009714f33476f92529dfb719c68a2.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @* ───── Step Indicator Bar ───── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        <div class="position-absolute" style="top: 20px; left: 10%; right: 10%; height: 2px; background: #dee2e6; z-index: 0;"></div>
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <div class="text-center position-relative" style="z-index: 1; flex: 1;">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center border-0 @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary opacity-50")"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture || _submitted)"
                        @onclick="() => GoToStep(step)">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                    @StepLabels[i]
                </div>
            </div>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger alert-dismissible fade show" role="alert">
            @_errorMessage
            <button type="button" class="btn-close" @onclick='() => _errorMessage = ""'></button>
        </div>
    }

    @if (_submitted)
    {
        @* ───── Confirmation ───── *@
        <div class="text-center py-5">
            <div class="display-1 text-success mb-3">✓</div>
            <h2>Application Submitted!</h2>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
            <p class="text-muted">Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        @* ───── Step 1: Personal Info ───── *@
        @if (_currentStep == 1)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Personal Information</h5></div>
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input class="form-control" @bind="_fullName" placeholder="John Doe" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="_email" placeholder="john@example.com" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <textarea class="form-control" @bind="_address" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
                    </div>
                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                            @if (_isValidating)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                                <span>Validating…</span>
                            }
                            else
                            {
                                <span>Next →</span>
                            }
                        </button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 2: Work History ───── *@
        @if (_currentStep == 2)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Work History</h5></div>
                <div class="card-body">
                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var index = i;
                        var entry = _workEntries[index];
                        <div class="border rounded p-3 mb-3 @(i > 0 ? "mt-2" : "")">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Position @(index + 1)</h6>
                                @if (_workEntries.Count > 1)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                                }
                            </div>
                            <div class="row mb-2">
                                <div class="col-md-6">
                                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="entry.Company" placeholder="Acme Corp" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="entry.Title" placeholder="Software Engineer" />
                                </div>
                            </div>
                            <div class="row mb-2">
                                <div class="col-md-4">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" @bind="entry.StartDate" />
                                </div>
                                <div class="col-md-4">
                                    <label class="form-label">End Date</label>
                                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                                </div>
                                <div class="col-md-4 d-flex align-items-end">
                                    <div class="form-check mb-2">
                                        <input class="form-check-input" type="checkbox" @bind="entry.IsCurrent" id="current-@index" />
                                        <label class="form-check-label" for="current-@index">Currently working here</label>
                                    </div>
                                </div>
                            </div>
                            <div class="mb-0">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" @bind="entry.Description" rows="2" placeholder="Describe your responsibilities…"></textarea>
                            </div>
                        </div>
                    }
                    <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="PrevStep">← Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next →</button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 3: References ───── *@
        @if (_currentStep == 3)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">References</h5></div>
                <div class="card-body">
                    @for (int i = 0; i < _references.Count; i++)
                    {
                        var index = i;
                        var r = _references[index];
                        <div class="border rounded p-3 mb-3">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Reference @(index + 1)</h6>
                                @if (_references.Count > 2)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                                }
                            </div>
                            <div class="row mb-2">
                                <div class="col-md-6">
                                    <label class="form-label">Name <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="r.Name" placeholder="Jane Smith" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                    <input class="form-control" @bind="r.Relationship" placeholder="Former Manager" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-6">
                                    <label class="form-label">Email <span class="text-danger">*</span></label>
                                    <input type="email" class="form-control" @bind="r.Email" placeholder="jane@example.com" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                                    <input type="tel" class="form-control" @bind="r.Phone" placeholder="(555) 987-6543" />
                                </div>
                            </div>
                        </div>
                    }
                    @if (_references.Count < 3)
                    {
                        <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">+ Add Reference</button>
                    }
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="PrevStep">← Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next →</button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 4: Cover Letter ───── *@
        @if (_currentStep == 4)
        {
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Cover Letter</h5></div>
                <div class="card-body">
                    <div class="mb-2">
                        <textarea class="form-control" @bind="_coverLetter" @bind:event="oninput" rows="12"
                                  placeholder="Write your cover letter here…" maxlength="2000"></textarea>
                    </div>
                    <div class="text-end text-muted small mb-3">
                        @(_coverLetter?.Length ?? 0) / 2000 characters
                    </div>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="PrevStep">← Back</button>
                        <button class="btn btn-primary" @onclick="NextStep">Next →</button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 5: Review & Submit ───── *@
        @if (_currentStep == 5)
        {
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-3">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mt-1 mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> — @r.Relationship<br />
                            <span class="text-muted">@r.Email · @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Cover Letter</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-outline-secondary" @onclick="PrevStep">← Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] StepLabels = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
    private const int TotalSteps = 5;

    private int _currentStep = 1;
    private string _errorMessage = "";
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    private async Task NextStep()
    {
        _errorMessage = "";

        if (!await ValidateCurrentStep())
            return;

        if (_currentStep < TotalSteps)
            _currentStep++;
    }

    private void PrevStep()
    {
        _errorMessage = "";
        if (_currentStep > 1)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= _currentStep && !_submitted)
        {
            _errorMessage = "";
            _currentStep = step;
        }
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _errorMessage = "Please fill in all required fields.";
                    return false;
                }
                _isValidating = true;
                try
                {
                    var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                    if (!emailValid)
                    {
                        _errorMessage = "Please enter a valid email address.";
                        return false;
                    }
                }
                finally
                {
                    _isValidating = false;
                }
                return true;

            case 2:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default)
                    {
                        _errorMessage = "Please fill in company name, job title, and start date for all positions.";
                        return false;
                    }
                }
                return true;

            case 3:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        _errorMessage = "Please fill in all fields for each reference.";
                        return false;
                    }
                }
                return true;

            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                {
                    _errorMessage = "Please write a cover letter.";
                    return false;
                }
                return true;

            default:
                return true;
        }
    }

    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);

    private async Task SubmitApplication()
    {
        _errorMessage = "";
        _isSubmitting = true;

        try
        {
            var personal = new PersonalInfo(_fullName.Trim(), _email.Trim(), _phone.Trim(), _address.Trim());
            var work = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company.Trim(), e.Title.Trim(), e.StartDate,
                    e.IsCurrent ? null : e.EndDate, e.Description?.Trim() ?? "")).ToList());
            var refs = _references.Select(r =>
                new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())).ToList();
            var application = new JobApplication(personal, work, refs, _coverLetter.Trim());

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
